let S : Finset ((a : Fin n) → a ∈ Finset.univ → Matrix (Fin 1) (Fin k) α) :=
  ((Finset.univ : Finset (Fin n)).pi
    (fun i => (filter (fun g : Matrix (Fin 1) (Fin k) α => (Matrix.mulVec g x = fun _ => v i)) Finset.univ)))

let S₂ :=
  (toFinset
    {g : Matrix (Fin 1) (Fin k) α | g 0 j = (v i - Finset.sum (erase Finset.univ j) fun a => g 0 a * x a) / x j})

let f : (g : Matrix (Fin 1) (Fin k) α) → g ∈ S₂ → (Codeword (k - 1) α) := fun g h_g =>
  (fun (l : Fin (k - 1)) =>
    if h_llt : l.val < j then (g 0 ⟨l.val, by exact h_k1 l⟩) else (g 0 ⟨l.val + 1, by exact h_k2 l⟩))

let φa :=
  (fun (l : Fin (k - 1)) =>
    if (l : ℕ) < (j : ℕ) then a 0 { val := ↑l, isLt := h_k1 l } else a 0 { val := ↑l + 1, isLt := h_k2 l })

let φb :=
  (fun (l : Fin (k - 1)) =>
    if (l : ℕ) < (j : ℕ) then b 0 { val := ↑l, isLt := h_k1 l } else b 0 { val := ↑l + 1, isLt := h_k2 l })

let p₀ : (Matrix (Fin 1) (Fin k) α) := fun _ l =>
  if h_lj : l < j then b ⟨l.val, by exact h_l1 l h_lj⟩
  else (if h_lj' : l = j then 0 else b ⟨l.val - 1, by exact h_l2 l h_lj h_lj'⟩)
